(() => {
  const fallbacks = {
    "hero": "data:image/webp;base64,",
    "logo": "data:image/webp;base64,",
    "shot1": "data:image/webp;base64,",
    "shot2": "data:image/webp;base64,",
    "shot3": "data:image/webp;base64,",
    "shot4": "data:image/webp;base64,",
    "shot5": "data:image/webp;base64,"
  };

  window.BRAWLZERK_IMAGE_FALLBACKS = fallbacks;

  const script = document.currentScript;
  const heroSource = script?.dataset.heroSrc || "../assets/media/BRAWLZERK_library_hero_3840x1240.png";

  const applyImageFallback = (image) => {
    if (!(image instanceof HTMLImageElement) || image.dataset.fallbackReady === "true") return;
    const fallback = fallbacks[image.dataset.inlineFallback];
    if (!fallback) return;

    image.dataset.fallbackReady = "true";
    image.addEventListener("error", () => {
      if (image.src === fallback) return;
      image.src = fallback;
      const slide = image.closest("[data-carousel-slide]");
      if (slide) slide.href = fallback;
    });
    if (image.complete && image.naturalWidth === 0) {
      image.src = fallback;
      const slide = image.closest("[data-carousel-slide]");
      if (slide) slide.href = fallback;
    }
  };

  const applyPosterFallback = (video) => {
    if (!(video instanceof HTMLVideoElement) || window.location.protocol !== "file:") return;
    const fallback = fallbacks[video.dataset.posterFallback];
    if (fallback) video.poster = fallback;
  };

  const scan = (root) => {
    if (root instanceof HTMLImageElement) applyImageFallback(root);
    if (root instanceof HTMLVideoElement) applyPosterFallback(root);
    root.querySelectorAll?.("img[data-inline-fallback]").forEach(applyImageFallback);
    root.querySelectorAll?.("video[data-poster-fallback]").forEach(applyPosterFallback);
  };

  scan(document);
  new MutationObserver((records) => {
    records.forEach((record) => record.addedNodes.forEach((node) => {
      if (node instanceof Element) scan(node);
    }));
  }).observe(document.documentElement, { childList: true, subtree: true });

  const heroProbe = new Image();
  heroProbe.addEventListener("error", () => {
    document.documentElement.style.setProperty("--hero-image", `url("${fallbacks.hero}")`);
  }, { once: true });
  heroProbe.src = new URL(heroSource, script?.src || window.location.href).href;
})();
